WITH session_totals AS (SELECT session_id, COUNT(DISTINCT duration_sec) AS unique_sessions, ROUND((100 * SUM(CASE WHEN page = '/product' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_product FROM web_events GROUP BY session_id) SELECT s.id, s.started_at, st.unique_sessions, st.pct_product FROM sessions s JOIN session_totals st ON s.id = st.session_id WHERE st.unique_sessions > 7 ORDER BY pct_product
